// ============================================================
// NEWS PARSER & CLEANER
// Parses RSS XML from all 5 sources, deduplicates, categorizes
// ============================================================

const allItems = $input.all();

// Helper: Parse RSS XML items from raw text
function parseRSSItems(xmlText, sourceName) {
  if (!xmlText || typeof xmlText !== 'string') return [];

  const results = [];
  // Extract all <item> blocks
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;

  while ((match = itemRegex.exec(xmlText)) !== null) {
    const block = match[1];

    // Extract title
    const titleMatch = block.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([^<]*)<\/title>/);
    const title = titleMatch ? (titleMatch[1] || titleMatch[2] || '').trim() : '';

    // Extract description
    const descMatch = block.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>|<description>([^<]*)<\/description>/);
    let desc = descMatch ? (descMatch[1] || descMatch[2] || '').trim() : '';
    // Strip HTML tags from description
    desc = desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 300);

    // Extract pubDate
    const dateMatch = block.match(/<pubDate>([^<]*)<\/pubDate>/);
    const pubDate = dateMatch ? dateMatch[1].trim() : '';

    if (title && title.length > 5) {
      results.push({ title, description: desc, pubDate, source: sourceName });
    }
  }

  return results;
}

// Source name mapping by index
const sourceNames = [
  'Economic Times Markets',
  'Moneycontrol',
  'Reuters India',
  'Google Finance News',
  'Global Market Cues'
];

// Collect all parsed news
let allNews = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const rawData = item.json?.data || item.json?.body || '';
  const sourceName = sourceNames[i] || `Source ${i + 1}`;

  const parsed = parseRSSItems(rawData, sourceName);
  allNews = allNews.concat(parsed);
}

// Deduplicate by title similarity (simple approach)
const seen = new Set();
const deduplicated = allNews.filter(news => {
  // Create a simplified key from first 60 chars of title
  const key = news.title.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 60);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Categorize news
function categorize(title, desc) {
  const text = (title + ' ' + desc).toLowerCase();

  if (/rbi|repo rate|monetary policy|inflation|cpi|gdp|rupee|usd|forex|fii|dii|institutional/i.test(text)) {
    return 'MACRO_ECONOMIC';
  }
  if (/nifty|sensex|bse|nse|index|benchmark|market open|market close/i.test(text)) {
    return 'BENCHMARK_INDEX';
  }
  if (/bank|banking|hdfc|icici|sbi|kotak|axis|nbfc/i.test(text)) {
    return 'BANKING_SECTOR';
  }
  if (/it|tcs|infosys|wipro|hcl|tech mahindra|software|technology/i.test(text)) {
    return 'IT_SECTOR';
  }
  if (/pharma|dr reddy|cipla|sun pharma|healthcare|hospital/i.test(text)) {
    return 'PHARMA_SECTOR';
  }
  if (/auto|tata motors|maruti|bajaj|hero|mahindra|automobile/i.test(text)) {
    return 'AUTO_SECTOR';
  }
  if (/crude|oil|gold|silver|commodity|metal|steel/i.test(text)) {
    return 'COMMODITY';
  }
  if (/dow|nasdaq|s&p|us market|global|asia|china|europe|fed|federal reserve|sgx/i.test(text)) {
    return 'GLOBAL_CUES';
  }
  if (/option|future|f&o|derivative|put|call|oi|open interest|vix/i.test(text)) {
    return 'FNO';
  }
  return 'GENERAL_MARKET';
}

// Apply categorization
const categorized = deduplicated.map(news => ({
  ...news,
  category: categorize(news.title, news.description)
}));

// Limit to 40 most recent/relevant items to avoid token overflow
const topNews = categorized.slice(0, 40);

// Format as structured text for AI prompt
const newsForAI = topNews.map((n, idx) => 
  `[${idx + 1}] [${n.category}] [${n.source}]\nTitle: ${n.title}\nSummary: ${n.description || 'N/A'}\nDate: ${n.pubDate || 'Recent'}`
).join('\n\n');

// Count by category for context
const catCounts = {};
topNews.forEach(n => {
  catCounts[n.category] = (catCounts[n.category] || 0) + 1;
});

return [{
  json: {
    newsText: newsForAI,
    totalArticles: topNews.length,
    categoryBreakdown: catCounts,
    fetchDate: new Date().toISOString()
  }
}];

// ============================================================
// FORMAT WHATSAPP MESSAGE
// Extract AI analysis and format for WhatsApp delivery
// ============================================================

const item = $input.first();
const responseData = item.json;

// Extract the AI generated content
let analysisText = '';

try {
  // Groq returns OpenAI-compatible format
  if (responseData.choices && responseData.choices[0]) {
    analysisText = responseData.choices[0].message?.content || '';
  } else if (responseData.content) {
    analysisText = responseData.content;
  } else {
    analysisText = JSON.stringify(responseData);
  }
} catch (e) {
  analysisText = 'Analysis generation mein error aaya. Please retry.';
}

// Get current IST time
const now = DateTime.now().setZone('Asia/Kolkata');
const dateStr = now.toFormat('dd MMM yyyy');
const timeStr = now.toFormat('hh:mm a');
const dayStr = now.toFormat('cccc'); // Full day name

// Build WhatsApp message header
const header = `📈 *DAILY MARKET INTELLIGENCE*
━━━━━━━━━━━━━━━━━━━━
📅 *${dayStr}, ${dateStr}*
⏰ Report Time: ${timeStr} IST
━━━━━━━━━━━━━━━━━━━━

`;

// Build footer
const footer = `
━━━━━━━━━━━━━━━━━━━━
🤖 *Powered by AI Market Intelligence*
📊 *Market Opens: 9:15 AM IST*
━━━━━━━━━━━━━━━━━━━━`;

// Final WhatsApp message
const whatsappMessage = header + analysisText + footer;

// WhatsApp has 4096 char limit — trim if needed
const finalMessage = whatsappMessage.length > 4000 
  ? whatsappMessage.substring(0, 3950) + '...\n\n[Message truncated - Full report available on request]'
  : whatsappMessage;

return [{
  json: {
    whatsappMessage: finalMessage,
    messageLength: finalMessage.length,
    reportDate: dateStr,
    generatedAt: now.toISO()
  }
}];

// ============================================================
// SUCCESS / FAILURE LOGGER
// Log execution result for monitoring
// ============================================================

const item = $input.first();
const now = DateTime.now().setZone('Asia/Kolkata');

const status = item.json?.messages?.[0]?.id ? 'SUCCESS' : 'SENT';

console.log(`[${now.toFormat('dd-MM-yyyy HH:mm:ss')} IST] Market Report ${status}`);
console.log(`WhatsApp Message ID: ${item.json?.messages?.[0]?.id || 'N/A'}`);

return [{
  json: {
    status: status,
    messageId: item.json?.messages?.[0]?.id || null,
    sentAt: now.toISO(),
    reportDate: now.toFormat('dd MMM yyyy')
  }
}];
